Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
xfrm: policy: fix use-after-free on inexact bin in
 xfrm_policy_bysel_ctx()

Fix the race by pruning the bin while still holding xfrm_policy_lock,
before dropping it. Use __xfrm_policy_inexact_prune_bin() directly since
the lock is already held. The wrapper xfrm_policy_inexact_prune_bin()
becomes unused and is removed.

Race:

  CPU0 (XFRM_MSG_DELPOLICY)           CPU1 (XFRM_MSG_NEWSPDINFO)
  ==========================          ==========================
  xfrm_policy_bysel_ctx():
    spin_lock_bh(xfrm_policy_lock)
    bin = xfrm_policy_inexact_lookup()
    __xfrm_policy_unlink(pol)
    spin_unlock_bh(xfrm_policy_lock)
    xfrm_policy_kill(ret)
    // wide window, lock not held
                                       xfrm_hash_rebuild():
                                         spin_lock_bh(xfrm_policy_lock)
                                         __xfrm_policy_inexact_flush():
                                           kfree_rcu(bin)  // bin freed
                                         spin_unlock_bh(xfrm_policy_lock)
    xfrm_policy_inexact_prune_bin(bin)
    // UAF: bin is freed

Fixes: 6be3b0db6db8 ("xfrm: policy: add inexact policy search tree infrastructure")
Signed-off-by: Sanghyun Park <sanghyun.park.cnu@gmail.com>
Signed-off-by: Steffen Klassert <steffen.klassert@secunet.com>

Here is the root cause:
Race condition in xfrm_policy_bysel_ctx() where the inexact bin is pruned after releasing xfrm_policy_lock, allowing another thread to free the bin via kfree_rcu before the pruning completes, leading to use-after-free.

Here is the patch:

-static void xfrm_policy_inexact_prune_bin(struct xfrm_pol_inexact_bin *b)
-{
-	struct net *net = read_pnet(&b->k.net);
-
-	spin_lock_bh(&net->xfrm.xfrm_policy_lock);
-	__xfrm_policy_inexact_prune_bin(b, false);
-	spin_unlock_bh(&net->xfrm.xfrm_policy_lock);
-}
-
 static void __xfrm_policy_inexact_flush(struct net *net)
 {
 	struct xfrm_pol_inexact_bin *bin, *t;

 	lockdep_assert_held(&net->xfrm.xfrm_policy_lock);

 	list_for_each_entry_safe(bin, t, &net->xfrm.inexact_bins, inexact_bins)
 		__xfrm_policy_inexact_prune_bin(bin, false);
 }


 struct xfrm_policy *
 xfrm_policy_bysel_ctx(struct net *net, const struct xfrm_mark *mark, u32 if_id,
 		      u8 type, int dir, struct xfrm_selector *sel,
 		      struct xfrm_sec_ctx *ctx, int delete, int *err)
 {
 	struct xfrm_pol_inexact_bin *bin = NULL;
 	struct xfrm_policy *pol, *ret = NULL;
 	struct hlist_head *chain;

 	*err = 0;
 	spin_lock_bh(&net->xfrm.xfrm_policy_lock);
 	chain = policy_hash_bysel(net, sel, sel->family, dir);
 	if (!chain) {
 		struct xfrm_pol_inexact_candidates cand;
 		int i;

 		bin = xfrm_policy_inexact_lookup(net, type,
 						 sel->family, dir, if_id);
 		if (!bin) {
 			spin_unlock_bh(&net->xfrm.xfrm_policy_lock);
 			return NULL;
 		}

 		if (!xfrm_policy_find_inexact_candidates(&cand, bin,
 							 &sel->saddr,
 							 &sel->daddr)) {
 			spin_unlock_bh(&net->xfrm.xfrm_policy_lock);
 			return NULL;
 		}

 		pol = NULL;
 		for (i = 0; i < ARRAY_SIZE(cand.res); i++) {
 			struct xfrm_policy *tmp;

 			tmp = __xfrm_policy_bysel_ctx(cand.res[i], mark,
 						      if_id, type, dir,
 						      sel, ctx);
 			if (!tmp)
 				continue;

 			if (!pol || tmp->pos < pol->pos)
 				pol = tmp;
 		}
 	} else {
 		pol = __xfrm_policy_bysel_ctx(chain, mark, if_id, type, dir,
 					      sel, ctx);
 	}

 	if (pol) {
 		xfrm_pol_hold(pol);
 		if (delete) {
 			*err = security_xfrm_policy_delete(pol->security);
 			if (*err) {
 				spin_unlock_bh(&net->xfrm.xfrm_policy_lock);
 				return pol;
 			}
 			__xfrm_policy_unlink(pol, dir);
 		}
 		ret = pol;
 	}
+	if (bin && delete)
+		__xfrm_policy_inexact_prune_bin(bin, false);
 	spin_unlock_bh(&net->xfrm.xfrm_policy_lock);

 	if (ret && delete)
 		xfrm_policy_kill(ret);
-	if (bin && delete)
-		xfrm_policy_inexact_prune_bin(bin);
 	return ret;
 }
 EXPORT_SYMBOL(xfrm_policy_bysel_ctx);


